sys_ui_action.script:
/**
 * UI action "Run assessment" - list banner button on Assessment Run.
 *
 * Inserts a queued run against the active connection. The async business
 * rule "Start queued assessment run" picks it up and executes the engine,
 * so this action returns immediately.
 */
var connection = new GlideRecord('x_cmdbgov_app_connection')
connection.addQuery('active', true)
connection.orderBy('name')
connection.setLimit(1)
connection.query()

if (!connection.next()) {
    gs.addErrorMessage(
        gs.getMessage('No active Governance Connection exists. Create one before running an assessment.')
    )
    action.setRedirectURL(current)
} else {
    var run = new GlideRecord('x_cmdbgov_app_run')
    run.initialize()
    run.setValue('connection', connection.getUniqueValue())
    run.setValue('state', 'queued')
    var runSysId = run.insert()

    if (runSysId) {
        gs.addInfoMessage(
            gs.getMessage('Assessment queued against "{0}". Refresh this list to watch it progress.', [
                connection.getValue('name'),
            ])
        )
        var target = new GlideRecord('x_cmdbgov_app_run')
        if (target.get(runSysId)) {
            action.setRedirectURL(target)
        } else {
            action.setRedirectURL(current)
        }
    } else {
        gs.addErrorMessage(gs.getMessage('Could not queue the assessment run.'))
        action.setRedirectURL(current)
    }
}
